        <Message
            at="2026-06-05T10:55:14.482064Z"
        >
            <Origin>019e976b-7850-7f08-9e7a-e2bcd728e78a</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Paragraph>
                Agreed — you've isolated it correctly. PayPal's signup runs a representative/beneficial-owner identity check
                no matter what, and on a Georgian IE the representative <Word>
                    <Emphasis />
                    is
                </Word> Ana, so the business flow lands on the identical gate: her face plus passport. Spinning up the
                business route as a workaround would just reproduce the same wall, so don't bother doing it for that reason.
            </Paragraph>
            <Paragraph>
                The only thing that still matters is something I can't read from outside: whether that face/passport step
                failed as a liveness-or-vendor tech failure (lighting, camera, the in-browser issue she already hit once) or
                as an eligibility screen reading a Russian passport against a Georgia account. Both present identically as
                "stuck at identity." The "we can't create your account" wording leans me toward the second, but that's a
                lean, not a verdict.
            </Paragraph>
            <Paragraph>Two things that actually follow from that.</Paragraph>
            <Paragraph>
                Don't keep retrying the face check. PayPal keys identity to passport plus face plus device, and repeated
                liveness failures can flag that record — which would make any later attempt worse, including a future
                business attempt and potentially other providers on the same device/passport. One clean attempt at most,
                then stop and make PayPal state the reason through the support message.
            </Paragraph>
            <Paragraph>
                And the fork is binary. If they come back with "the Georgian business basis plus passport is fine, that was
                a glitch" → retry clean and you're through. If they come back with "we need a Georgian residence document" →
                that's the wall, and neither the IBAN nor the business setup moves it an inch. That second branch is where
                Payoneer becomes the better bet — not because it skips the face/passport check (it runs one too), but
                because the eligibility rule sitting behind its check is residence-by-address-proof rather than a permit,
                which Ana can plausibly meet. Better odds, not a guarantee.
            </Paragraph>
            <Paragraph>
                So the support answer isn't really about fixing PayPal — it's the cheapest way to find out which branch
                you're on before committing effort to either rail.
            </Paragraph>
        </Message>
