        <Message
            at="2026-06-05T11:20:26.030199Z"
        >
            <Origin>019e9783-32e3-79b9-baba-0b079bcba607</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Paragraph>
                Да, идём дальше — всё логично. Страна регистрации Грузия — верно (бизнес зарегистрирован в Грузии, это
                подтверждено выпиской). Сейчас шаг <Word>
                    <Bold />
                    Mobile number
                </Word> — он есть в списке слева, ты движешься по порядку.
            </Paragraph>
            <Paragraph>Пара уточнений по номеру, чтобы потом не споткнуться:</Paragraph>
            <Paragraph>
                <List />
                <Line>
                    Указывай <Word>
                        <Bold />
                        грузинский номер (+995)
                    </Word>, тот, которым реально пользуешься и к которому есть доступ прямо сейчас — на него придёт SMS с
                    кодом, его надо будет ввести тут же.
                </Line>
                <Line>
                    Лучше тот номер, что <Word>
                        <Bold />
                        привязан к Mycredo / к твоим грузинским сервисам
                    </Word> — меньше путаницы потом при сверках.
                </Line>
                <Line>
                    Если номер российский (+7) — не бери его: это лишний сигнал «Россия» там, где мы как раз строим
                    грузинский профиль. Грузинский номер усиливает привязку к Грузии.
                </Line>
            </Paragraph>
            <Paragraph>
                Вводи грузинский номер, получай SMS, подтверждай код — дальше будет шаг <Word>
                    <Bold />
                    Password
                </Word>. После него начнётся часть посерьёзнее: данные бизнеса, адрес и верификация личности. Туда подойдём
                — держи под рукой выписку (B26372149) и загранпаспорт.
            </Paragraph>
            <Paragraph>Иди дальше и, если на следующем экране будет что-то неоднозначное, кидай сюда.</Paragraph>
        </Message>
