        <Message
            at="2026-06-05T11:29:20.766593Z"
        >
            <Origin>019e978b-41fa-7139-b9b3-09b4e6af23fa</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Paragraph>Хороший вопрос, и тут есть важный нюанс — поэтому давай не наугад.</Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    В документах (выписке) вида деятельности НЕТ.
                </Word> Грузинский IE регистрируется без привязки к конкретному коду деятельности — в выписке B26372149
                указаны только форма, название, адрес и владелец. Так что «как в документах» тут не сработает — выбирать
                придётся по сути того, чем ты реально занимаешься.
            </Paragraph>
            <Paragraph>
                А занимаешься ты, как я понимаю, <Word>
                    <Bold />
                    картографией и иллюстрацией
                </Word> (Fiverr) плюс работа с научной лабораторией. То есть это творческие/дизайнерские услуги.
            </Paragraph>
            <Paragraph>
                Поле — это поиск с выпадающим списком (там предзаданные категории Payoneer). Я не вижу самих вариантов, пока
                ты не начнёшь печатать. Попробуй вбить по очереди и посмотри, что предложит:
            </Paragraph>
            <Paragraph>
                <List />
                <Line>
                    <Word>
                        <Bold />
                        design
                    </Word> → скорее всего будет что-то вроде <Word>
                        <Emphasis />
                        Graphic / Design services
                    </Word>
                </Line>
                <Line>
                    <Word>
                        <Bold />
                        illustration
                    </Word> или <Word>
                        <Bold />
                        art
                    </Word>
                </Line>
                <Line>
                    <Word>
                        <Bold />
                        creative
                    </Word>
                </Line>
                <Line>
                    <Word>
                        <Bold />
                        freelance
                    </Word>
                </Line>
                <Line>
                    <Word>
                        <Bold />
                        map
                    </Word> / <Word>
                        <Bold />
                        cartography
                    </Word> (вряд ли есть отдельно, но проверь)
                </Line>
            </Paragraph>
            <Paragraph>
                Из того, что обычно есть у Payoneer, тебе ближе всего категория уровня <Word>
                    <Bold />
                    «Graphic Design / Creative Services»
                </Word> или <Word>
                    <Bold />
                    «Freelance / Professional Services»
                </Word>.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Но прежде чем выбрать — один момент по твоей 1% позиции.
                </Word> Мы это уже обсуждали в контексте налогов: важно, чтобы деятельность читалась как <Word>
                    <Bold />
                    поставка работы/продукта
                </Word> (дизайн, иллюстрация, карты — это результат, артефакт), а не как размытый <Word>
                    <Bold />
                    «консалтинг/советы»
                </Word>. Для Payoneer это не критично так, как для грузинской налоговой, но логично держать формулировку
                единой везде. Так что если в списке будет выбор между «Design / Creative services» и «Consulting» — бери
                <Word>
                    <Bold />
                    дизайн/креатив
                </Word>, не консалтинг.
            </Paragraph>
            <Paragraph>
                Практически: начни печатать <Word>
                    <Verbatim />
                    design
                </Word>, потом <Word>
                    <Verbatim />
                    illustration
                </Word>, потом <Word>
                    <Verbatim />
                    creative
                </Word> — и <Word>
                    <Bold />
                    пришли мне скрин выпадающего списка
                </Word> с вариантами, которые он покажет. Тогда я скажу точно, какой пункт ближе всего к тому, что ты
                делаешь, а не буду гадать по памяти о том, какие категории у Payoneer сейчас. Что он предложит?
            </Paragraph>
        </Message>
